using EnterpriseDocumentIntelligence.AgentService.Domain; namespace EnterpriseDocumentIntelligence.AgentService.Application; public interface IAgentConversationStore{Task<AgentConversation?> GetAsync(Guid id,CancellationToken ct=default);Task SaveAsync(AgentConversation conversation,CancellationToken ct=default);} public sealed class AgentApplication(IAgentConversationStore store){public async Task<AgentConversation> StartAsync(Guid id,string tenantId,string prompt,CancellationToken ct=default){var c=await store.GetAsync(id,ct)??new AgentConversation(id,tenantId);c.Add(new AgentTurn(AgentTurnRole.User,prompt));await store.SaveAsync(c,ct);return c;}}